// Demo: Vehicle Routing Solver - Signature build-tool concept
(function(){'use strict';
var DATA={"label": "Vehicle Routing Solver - Signature build-tool concept", "nodes": ["Vehicle", "Routing", "Solver", "Planning", "scheduling"], "edges": [["Vehicle", "Routing"], ["Routing", "Solver"], ["Solver", "Planning"], ["Planning", "scheduling"]]};

var nodes=DATA.nodes, edges=DATA.edges, indeg={}, adj={};
nodes.forEach(function(n){indeg[n]=0;adj[n]=[];});
edges.forEach(function(e){adj[e[0]].push(e[1]);indeg[e[1]]++;});
var q=nodes.filter(function(n){return indeg[n]===0;}), order=[];
console.log('Topological build order for: '+DATA.label);
while(q.length){var n=q.shift();order.push(n);
  adj[n].forEach(function(m){indeg[m]--;if(indeg[m]===0)q.push(m);});}
if(order.length!==nodes.length){console.log('CYCLE DETECTED - no valid build order');}
else{order.forEach(function(n,i){console.log(' step '+(i+1)+': build '+n);});
console.log('OK - '+order.length+' components in dependency order');}
})();

